-- V19__add_activity_subcategory_and_image_pools.sql
-- Add subcategory_id and image_strategy to activities table
-- Establishes visual taxonomy and image resolution strategy across all 926 pre-seeded activities

ALTER TABLE activities ADD COLUMN IF NOT EXISTS subcategory_id VARCHAR(64);
ALTER TABLE activities ADD COLUMN IF NOT EXISTS image_strategy VARCHAR(32) DEFAULT 'SHARED_IMAGE_POOL';
CREATE INDEX IF NOT EXISTS idx_activities_subcat ON activities(subcategory_id);

